// #dbea28b76137e3b7198da386 — фон страниц бизнеса = синий градиент утверждённых кадров 693:3144, 678:652, 812:448, 816:1183.
// Кейсы BG-001, BG-002. Только чтение — @prod-safe. Окно 1440×1024 (как кадры Figma), снимок окна (не fullPage: у fixed-фона склейка).
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '@playwright/test';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/business.json'),
  viewport: { width: 1440, height: 1024 },
});

const REPORT_ID = '7ade4110-48a9-4f1d-9835-b3ecb102cbcc'; // длинный отчёт кандидата testim (QA-данные)
const TOLERANCE = 12;
// Точки чистого фона и цвета из кадров Figma (во всех 4 кадрах фон одинаков).
const FIGMA = {
  topLeft: { x: 10, y: 10, rgb: [52, 78, 191] },
  topRight: { x: 1432, y: 10, rgb: [40, 62, 152] },
  midRight: { x: 1432, y: 512, rgb: [22, 24, 29] },
  bottomLeft: { x: 10, y: 1012, rgb: [31, 46, 103] },
} as const;
type Point = (typeof FIGMA)[keyof typeof FIGMA];

/** Цвета пикселей снимка окна в заданных точках (декодирование PNG через canvas в отдельной вкладке). */
async function samplePixels(page: Page, points: readonly Point[]) {
  const png = await page.screenshot();
  const probe = await page.context().newPage();
  try {
    await probe.setContent('<canvas></canvas>');
    return await probe.evaluate(
      async ({ b64, pts }) => {
        const img = new Image();
        img.src = `data:image/png;base64,${b64}`;
        await img.decode();
        const c = document.querySelector('canvas')!;
        c.width = img.width;
        c.height = img.height;
        const ctx = c.getContext('2d')!;
        ctx.drawImage(img, 0, 0);
        return pts.map((p) => Array.from(ctx.getImageData(p.x, p.y, 1, 1).data.slice(0, 3)));
      },
      { b64: png.toString('base64'), pts: points.map(({ x, y }) => ({ x, y })) },
    );
  } finally {
    await probe.close();
  }
}

async function expectGradientBackground(page: Page, points: readonly Point[]) {
  const style = await page.evaluate(() => {
    const b = getComputedStyle(document.body);
    const h = getComputedStyle(document.documentElement);
    return { image: b.backgroundImage, attachment: b.backgroundAttachment, colors: [b.backgroundColor, h.backgroundColor], htmlImage: h.backgroundImage };
  });
  // Источник: «מצב נוכחי» тикета — старый фон «background-vector.svg מעל #414a57».
  expect(style.image).toContain('radial-gradient');
  expect(style.image + style.htmlImage).not.toContain('background-vector');
  expect(style.colors).not.toContain('rgb(65, 74, 87)');
  expect(style.attachment).toContain('fixed');

  // Источник: AC — «רקע העמודים בצד העסק תואם את מעבר הצבע הכחול של המסגרות המאושרות 693:3144, 678:652, 812:448 ו-816:1183».
  const got = await samplePixels(page, points);
  points.forEach((p, i) => {
    const diff = Math.max(...p.rgb.map((v, k) => Math.abs(v - got[i][k])));
    expect(diff, `точка (${p.x},${p.y}): сайт ${got[i].join(',')} vs Figma ${p.rgb.join(',')}`).toBeLessThanOrEqual(TOLERANCE);
  });
}

test.describe('Фон страниц бизнеса — синий градиент (#dbea28b76137e3b7198da386)', () => {
  for (const url of ['/', '/candidates', '/simulations', '/settings']) {
    test(`${url}: градиент вместо background-vector/#414a57, точки фона = Figma @desktop @prod-safe #dbea28b76137e3b7198da386`, async ({ page }) => {
      await page.goto(url);
      await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();
      await expectGradientBackground(page, Object.values(FIGMA));
    });
  }

  test('длинный отчёт: внизу после прокрутки тот же градиент, без обрыва @desktop @prod-safe #dbea28b76137e3b7198da386', async ({ page }) => {
    await page.goto(`/candidates/${REPORT_ID}/report`);
    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();
    const height = await page.evaluate(() => document.documentElement.scrollHeight);
    expect(height, 'предусловие: страница длиннее окна').toBeGreaterThan(1024);
    await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
    await expect.poll(() => page.evaluate(() => Math.ceil(window.scrollY + window.innerHeight) >= document.documentElement.scrollHeight - 1)).toBe(true);
    await expectGradientBackground(page, [FIGMA.midRight, FIGMA.bottomLeft]);
  });
});
